\begin{theorem}[Modified global derivative estimates]
\label{thm:chow-ii-appd-modified-global-derivative-estimates}
\source{chow-et-al-ricci-flow-part-ii:page-0394}
\uses{thm:chow-ii-shi-estimates-initial-derivative-bounds}
\dcref{appD:D.25}
\group{Curvature Derivative Estimates}


In the setting of Theorem~\ref{thm:chow-ii-appd-local-derivative-estimates},
assume additionally that $|\nabla^k\operatorname{Rm}(\cdot,0)|\leq K$ for
$k\leq\ell$. Then on the half-radius ball
\[
 |\nabla^m\operatorname{Rm}(y,t)|\leq
 \frac C{t^{\max\{m-\ell,0\}/2}}.
\]
\end{theorem}

